namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var allocations = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        if (remaining <= 0)
            return allocations;

        AllocateAcrossZones(warehouse, allocations, ref remaining);
        AddOverflowAllocation(allocations, remaining);
        return allocations;
    }

    private static void AllocateAcrossZones(
        Warehouse warehouse,
        List<string> allocations,
        ref int remaining)
    {
        foreach (var zone in warehouse.Zones)
        {
            if (!TryCalculatePlacement(zone.Name, zone.Capacity, remaining, out int placement))
                continue;

            allocations.Add($"{zone.Name}:{placement}");
            remaining -= placement;

            if (remaining <= 0)
                break;
        }
    }

    private static bool TryCalculatePlacement(
        string? zoneName,
        int capacity,
        int remaining,
        out int placement)
    {
        placement = 0;
        if (capacity <= 0 || string.IsNullOrEmpty(zoneName))
            return false;

        placement = CalculatePlacement(capacity, remaining);
        return placement > 0;
    }

    private static int CalculatePlacement(int capacity, int remaining)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2
            ? remaining - 1
            : remaining;
    }

    private static void AddOverflowAllocation(List<string> allocations, int remaining)
    {
        if (remaining > 0)
            allocations.Add($"OVERFLOW:{remaining}");
    }
}
